# SOLUTION 1
class TextFileManager_Solution:
    def __init__(self, filename, mode="r"):
        self.filename = filename
        self.mode = mode
        self.file = None
        self.line_count = 0

    def __enter__(self):
        self.file = open(self.filename, self.mode)
        return self.file

    def __exit__(self, exc_type, exc_value, traceback):
        if self.file:
            if self.mode == "r":
                self.file.seek(0)
                self.line_count = len(self.file.readlines())
            self.file.close()
            print(f"Read {self.line_count} lines from {self.filename}")
        return False

